from annotation import vep_columns
from annotation.enums import VEPPlugin
from annotation.vep_config import vep_component_version_kwargs

# VariantAnnotationVersion pin field -> the plugin whose data file it pins
_PLUGIN_PINS = {
    "utr_annotator": VEPPlugin.UTR_ANNOTATOR,
    "avi": VEPPlugin.AVI,
    "splicevault": VEPPlugin.SPLICEVAULT,
}
BACKFILL_FLAG = "backfilled_utr_avi_splicevault"


def _stamp_pins_and_flag_backfill(apps, _schema_editor):
    """ Stamp the plugins' pins on the versions the scheduler can still match, from live settings.
        Left NULL while settings name the file, every run would fail with VEPVersionMismatchError and
        create_new_variant_annotation_version would mint a new version - a full re-annotation.

        A version that has annotated variants, at a build / columns_version / VEP one of the plugins'
        columns cover, holds them without it - it is flagged for the backfill. HISTORICAL versions are
        left alone: nothing looks them up by config again. """
    VariantAnnotationVersion = apps.get_model("annotation", "VariantAnnotationVersion")
    AnnotationRangeLock = apps.get_model("annotation", "AnnotationRangeLock")
    for vav in VariantAnnotationVersion.objects.filter(status__in=["NEW", "ACTIVE"]):
        build_settings = settings.ANNOTATION.get(vav.genome_build_id)
        if build_settings is None:
            continue  # Build no longer configured on this deployment
        pins = vep_component_version_kwargs(build_settings)
        plugin_applies = False
        for field, vep_plugin in _PLUGIN_PINS.items():
            setattr(vav, field, pins[field])
            plugin_columns = vep_columns.filter_for(vep_plugin=vep_plugin,
                                                    genome_build_name=vav.genome_build_id,
                                                    columns_version=vav.columns_version,
                                                    vep_version=vav.vep)
            plugin_applies |= bool(pins[field] and plugin_columns)
        has_annotation = AnnotationRangeLock.objects.filter(version=vav).exists()
        setattr(vav, BACKFILL_FLAG, not (plugin_applies and has_annotation))
        vav.save(update_fields=[*_PLUGIN_PINS, BACKFILL_FLAG])


